const passport = require('passport');
const CustomStrategy = require('passport-custom').Strategy;
const { Cart, User } = require('../db');

passport.use('guest-merge', new CustomStrategy(async (req, done) => {
  const { guestCartId } = req.body;
  const expectedGuestSession = req.session?.guestCartToken;
  if (!guestCartId || !req.user) return done(null, req.user);

  const guestCart = await Cart.findOne({
    where: { id: guestCartId, sessionToken: expectedGuestSession, userId: null }
  });
  if (!guestCart) {
    return done(null, false, { message: 'Invalid or expired guest cart session' });
  }

  await guestCart.update({ userId: req.user.id });
  return done(null, req.user);
}));
